//! Platform-specific UI entry point.
//!
//! The mobile targets (Android / iOS) receive a native window handle and use
//! the platform's GPU context (Vulkan via wgpu on Android, Metal via wgpu on
//! iOS).  On desktop (feature = "desktop") the native_window_ptr is ignored
//! and a standard OS window is created via eframe.
//!
//! This file contains only stubs that document the integration contract.
//! The full per-platform glue is generated by `cargo-mobile` and linked here.

/// Entry point called from `start_ui`.
///
/// # Arguments
/// * `daemon_addr` — gRPC address, e.g. `"http://127.0.0.1:50051"`.
/// * `native_window_ptr` — platform-specific window handle (as usize).
/// * `width`, `height` — initial surface dimensions in physical pixels.
pub fn run_ui(daemon_addr: &str, native_window_ptr: usize, width: u32, height: u32) {
    #[cfg(target_os = "android")]
    android::run(daemon_addr, native_window_ptr, width, height);

    #[cfg(target_os = "ios")]
    ios::run(daemon_addr, native_window_ptr, width, height);

    #[cfg(not(any(target_os = "android", target_os = "ios")))]
    desktop::run(daemon_addr, width, height);
}

