// ---------------------------------------------------------------------------
// Desktop fallback (always compiled on non-mobile targets)
// ---------------------------------------------------------------------------

#[cfg(not(any(target_os = "android", target_os = "ios")))]
mod desktop {
    /// On desktop, ignore the native window handle and use eframe's own window.
    /// This path is exercised by the mobile-crate integration tests.
    pub fn run(addr: &str, _width: u32, _height: u32) {
        // In a test or desktop context the UI runs via eframe::run_native.
        // The mobile crate's tests call this through `start_daemon_and_connect`
        // rather than through `run_ui`, so this is a no-op placeholder.
        eprintln!("[mobile/desktop] run_ui called for addr={addr} (no-op on desktop)");
    }
}
